// 國際化 (i18n) 管理系統
class I18n {
  constructor() {
    this.currentLanguage = 'zh-TW'; // 預設繁中（台灣為主要市場）
    this.translations = {};
    this.supportedLanguages = ['en', 'zh-TW', 'ja', 'es'];
    this.languageNames = {
      'en': 'English',
      'zh-TW': '繁體中文',
      'ja': '日本語',
      'es': 'Español'
    };
    this.documentClickBound = false; // 追蹤是否已綁定 document click

    this.init();
  }

  init() {
    // 偵測用戶語言偏好
    const detectedLang = this.detectLanguage();
    this.loadLanguage(detectedLang);
    this.updateContent();
    this.setupLanguageSwitcher();
  }

  detectLanguage() {
    // 1. 檢查 localStorage 中的偏好設定
    const storedLang = localStorage.getItem('preferred-language');
    if (storedLang && this.supportedLanguages.includes(storedLang)) {
      return storedLang;
    }

    // 2. 檢查瀏覽器語言設定
    const browserLang = navigator.language || navigator.languages?.[0];

    // 語言映射表
    const languageMapping = {
      'zh-TW': 'zh-TW',
      'zh-HK': 'zh-TW',
      'zh-CN': 'zh-TW', // 簡體也顯示繁體
      'zh': 'zh-TW',
      'ja': 'ja',
      'ja-JP': 'ja',
      'es': 'es',
      'es-ES': 'es',
      'es-MX': 'es',
      'es-AR': 'es',
      'en': 'en',
      'en-US': 'en',
      'en-GB': 'en'
    };

    // 檢查完整語言代碼
    if (languageMapping[browserLang]) {
      return languageMapping[browserLang];
    }

    // 檢查語言代碼的主要部分
    const mainLang = browserLang?.split('-')[0];
    if (languageMapping[mainLang]) {
      return languageMapping[mainLang];
    }

    // 預設返回繁中（台灣為主要市場）
    return 'zh-TW';
  }

  // persist：只有用戶手動切換才寫入 localStorage；自動偵測不寫，瀏覽器語言改了才會跟著變
  loadLanguage(lang, persist = false) {
    if (!this.supportedLanguages.includes(lang)) {
      lang = 'zh-TW'; // 回退到繁中
    }

    try {
      // 從嵌入的語言資料讀取
      if (LANGUAGE_DATA[lang]) {
        this.translations = LANGUAGE_DATA[lang];
        this.currentLanguage = lang;

        // 儲存用戶偏好（僅手動切換）
        if (persist) localStorage.setItem('preferred-language', lang);

        // 更新 HTML lang 屬性
        document.documentElement.lang = lang;
      } else {
        throw new Error(`Language data not found: ${lang}`);
      }
    } catch (error) {
      console.error('Error loading language:', error);

      // 如果不是英文且載入失敗，回退到英文
      if (lang !== 'en') {
        this.loadLanguage('zh-TW');
      }
    }
  }

  getText(key) {
    const keys = key.split('.');
    let value = this.translations;

    for (const k of keys) {
      // 處理陣列索引
      if (!isNaN(k) && Array.isArray(value)) {
        value = value[parseInt(k)];
      } else {
        value = value?.[k];
      }
      if (value === undefined) break;
    }

    return value || key; // 如果找不到翻譯，返回原 key
  }

  updateContent() {
    // 更新所有具有 data-i18n 屬性的元素
    const elements = document.querySelectorAll('[data-i18n]');

    elements.forEach(element => {
      const key = element.getAttribute('data-i18n');
      const text = this.getText(key);

      if (text && text !== key) {
        // 檢查是否是輸入框的 placeholder
        if (element.hasAttribute('placeholder')) {
          element.setAttribute('placeholder', text);
        } else {
          // 特殊處理：英日西語言在手機版的下載標題換行
          if (key === 'download.title' &&
              ['en', 'ja', 'es'].includes(this.currentLanguage) &&
              window.innerWidth <= 640) {
            element.innerHTML = text.replace(' - ', '<br>- ');
          } else {
            // {year} 佔位符 → 當前年份(footer 版權動態年份;每次切語言重跑也維持正確)
            // getText 可能回傳非字串(例如 key 指到陣列/物件),先判型再 replace,避免整個 i18n 迴圈被 TypeError 中斷
            element.textContent = typeof text === 'string'
              ? text.replace('{year}', new Date().getFullYear())
              : text;
          }
        }
      }
    });

    // 依語言切換圖片：data-i18n-src 的值是不含副檔名的路徑，<picture> 的 webp source 與 img 的 jpg 一起換
    document.querySelectorAll('[data-i18n-src]').forEach(element => {
      const base = this.getText(element.getAttribute('data-i18n-src'));
      if (typeof base !== 'string' || !base.startsWith('assets/')) return;
      const source = element.parentElement?.querySelector('source[type="image/webp"]');
      if (source) source.srcset = base + '.webp';
      if (element.getAttribute('src') !== base + '.jpg') element.src = base + '.jpg';
    });

    // 更新所有具有 data-i18n-alt 屬性的圖片 alt 文字
    const altElements = document.querySelectorAll('[data-i18n-alt]');
    altElements.forEach(element => {
      const key = element.getAttribute('data-i18n-alt');
      const text = this.getText(key);
      if (text && text !== key) {
        element.setAttribute('alt', text);
      }
    });

    // 更新 meta 標籤
    this.updateMetaTags();
  }

  updateMetaTags() {
    // 更新 title
    if (this.translations.meta?.title) {
      document.title = this.translations.meta.title;
    }

    // 更新 meta description
    const metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc && this.translations.meta?.description) {
      metaDesc.setAttribute('content', this.translations.meta.description);
    }

    // 更新 og:title
    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle && this.translations.og?.title) {
      ogTitle.setAttribute('content', this.translations.og.title);
    }

    // 更新 og:description
    const ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc && this.translations.og?.description) {
      ogDesc.setAttribute('content', this.translations.og.description);
    }
  }

  setupLanguageSwitcher() {
    // 建立語言切換器
    this.createLanguageSwitcher();
  }

  createLanguageSwitcher() {
    // 檢查是否已存在語言切換器
    if (document.querySelector('.language-switcher')) {
      return;
    }

    // 建立語言切換器容器
    const switcher = document.createElement('div');
    switcher.className = 'language-switcher';

    // 建立當前語言顯示按鈕
    const currentLangBtn = document.createElement('button');
    currentLangBtn.className = 'current-language';
    currentLangBtn.textContent = this.languageNames[this.currentLanguage];
    currentLangBtn.setAttribute('aria-label', 'Language selector');

    // 建立語言選項下拉選單
    const dropdown = document.createElement('div');
    dropdown.className = 'language-dropdown';

    this.supportedLanguages.forEach(lang => {
      if (lang !== this.currentLanguage) {
        const option = document.createElement('button');
        option.className = 'language-option';
        option.textContent = this.languageNames[lang];
        option.setAttribute('data-lang', lang);

        // 使用立即執行函數避免閉包問題
        ((selectedLang) => {
          option.addEventListener('click', (e) => {
            e.stopPropagation();
            this.switchLanguage(selectedLang);
          });
        })(lang);

        dropdown.appendChild(option);
      }
    });

    // 組裝語言切換器
    switcher.appendChild(currentLangBtn);
    switcher.appendChild(dropdown);

    // 加入到頁面底部的聯絡資訊區
    const contactInfo = document.querySelector('.contact-info');
    if (contactInfo) {
      contactInfo.appendChild(switcher);
    }

    // 點擊切換下拉選單顯示/隱藏
    currentLangBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      dropdown.classList.toggle('show');
    });

    // 點擊其他地方關閉下拉選單（只綁定一次）
    if (!this.documentClickBound) {
      document.addEventListener('click', () => {
        const anyDropdown = document.querySelector('.language-dropdown.show');
        if (anyDropdown) {
          anyDropdown.classList.remove('show');
        }
      });
      this.documentClickBound = true;
    }
  }

  switchLanguage(lang) {
    if (lang === this.currentLanguage) return;

    this.loadLanguage(lang, true);
    this.updateContent();

    // 更新語言切換器
    const switcher = document.querySelector('.language-switcher');
    if (switcher) {
      switcher.remove();
      this.createLanguageSwitcher();
    }
  }
}

// 初始化國際化系統
document.addEventListener('DOMContentLoaded', () => {
  const i18n = new I18n();
  // 導出給其他腳本使用
  window.i18n = i18n;
});